// src/pages/admin/AdminPagesList.js
import React, { useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import api from "../../api";
import "./AdminPages.css";

/* ---------------------------
   Tiny Toast System (no deps)
---------------------------- */
function useToasts() {
  const [toasts, setToasts] = useState([]);

  function push(type, message, ms = 2800) {
    const id = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
    setToasts((prev) => [...prev, { id, type, message }]);
    window.setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, ms);
  }

  return {
    toasts,
    success: (msg, ms) => push("success", msg, ms),
    error: (msg, ms) => push("error", msg, ms),
    info: (msg, ms) => push("info", msg, ms),
  };
}

function ToastHost({ items }) {
  return (
    <div
      style={{
        position: "fixed",
        right: 18,
        top: 18,
        zIndex: 9999,
        display: "grid",
        gap: 10,
        width: 360,
        maxWidth: "calc(100vw - 36px)",
      }}
    >
      {items.map((t) => (
        <div
          key={t.id}
          role="status"
          style={{
            borderRadius: 12,
            padding: "12px 14px",
            border: "1px solid rgba(255,255,255,0.10)",
            background:
              t.type === "success"
                ? "linear-gradient(180deg, rgba(46,204,113,0.22), rgba(255,255,255,0.06))"
                : t.type === "error"
                  ? "linear-gradient(180deg, rgba(255,91,91,0.22), rgba(255,255,255,0.06))"
                  : "linear-gradient(180deg, rgba(154,92,255,0.18), rgba(255,255,255,0.06))",
            boxShadow: "0 18px 48px rgba(0,0,0,0.45)",
            color: "rgba(255,255,255,0.92)",
            fontSize: 14,
          }}
        >
          <div style={{ fontWeight: 700, marginBottom: 4 }}>
            {t.type === "success"
              ? "Success"
              : t.type === "error"
                ? "Error"
                : "Info"}
          </div>
          <div style={{ color: "rgba(255,255,255,0.78)", lineHeight: 1.35 }}>
            {t.message}
          </div>
        </div>
      ))}
    </div>
  );
}

/* ---------------------------
   Modern Modal (no deps)
---------------------------- */
function Modal({ open, title, children, onClose }) {
  useEffect(() => {
    if (!open) return;
    const onKey = (e) => {
      if (e.key === "Escape") onClose?.();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  if (!open) return null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      onMouseDown={(e) => {
        // click outside to close
        if (e.target === e.currentTarget) onClose?.();
      }}
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 9998,
        background: "rgba(0,0,0,0.62)",
        display: "grid",
        placeItems: "center",
        padding: 16,
      }}
    >
      <div
        style={{
          width: 520,
          maxWidth: "100%",
          borderRadius: 16,
          border: "1px solid rgba(255,255,255,0.10)",
          background:
            "linear-gradient(180deg, rgba(255,255,255,0.08), rgba(255,255,255,0.04))",
          boxShadow: "0 28px 70px rgba(0,0,0,0.60)",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            padding: "14px 16px",
            borderBottom: "1px solid rgba(255,255,255,0.08)",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 12,
          }}
        >
          <div style={{ fontWeight: 800, color: "rgba(255,255,255,0.92)" }}>
            {title}
          </div>
          <button
            className="ap-btn"
            onClick={onClose}
            style={{ padding: "6px 10px" }}
          >
            ✕
          </button>
        </div>

        <div style={{ padding: 16 }}>{children}</div>
      </div>
    </div>
  );
}

function slugify(s) {
  return String(s || "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

export default function AdminPagesList() {
  const nav = useNavigate();
  const toast = useToasts();

  const [pages, setPages] = useState([]);
  const [loading, setLoading] = useState(true);

  // New Page modal state
  const [openNew, setOpenNew] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newSlug, setNewSlug] = useState("");
  const [creating, setCreating] = useState(false);
  const titleRef = useRef(null);

  useEffect(() => {
    if (openNew) {
      setTimeout(() => titleRef.current?.focus?.(), 50);
    }
  }, [openNew]);

  // Keep slug auto-generated unless user edits it
  const autoSlug = useMemo(() => slugify(newTitle), [newTitle]);

  useEffect(() => {
    // if slug is empty, keep in sync with title
    if (!openNew) return;
    if (!newSlug) setNewSlug(autoSlug);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoSlug, openNew]);

  async function load() {
    setLoading(true);
    try {
      const r = await api.get("/admin/pages");
      setPages(r.data.pages || []);
    } catch (e) {
      console.error(e);
      toast.error("Failed to load pages.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function openCreate() {
    setNewTitle("");
    setNewSlug("");
    setOpenNew(true);
  }

  function closeCreate() {
    if (creating) return;
    setOpenNew(false);
  }

  async function confirmCreate() {
    const title = String(newTitle || "").trim();
    const slug = slugify(newSlug || "");

    if (!title) {
      toast.error("Please enter a page title.");
      titleRef.current?.focus?.();
      return;
    }
    if (!slug) {
      toast.error("Please enter a valid slug.");
      return;
    }

    setCreating(true);
    try {
      const r = await api.post("/admin/pages", {
        title,
        slug,
        // Seed builder container so you can add sections/blocks immediately
        content_json: { extra_sections: [] },
      });
      toast.success("Page created.");
      setOpenNew(false);
      nav(`/admin/pages/${r.data.page.id}`);
    } catch (e) {
      toast.error(e?.response?.data?.error || "Create failed.");
    } finally {
      setCreating(false);
    }
  }

  async function publish(id) {
    try {
      await api.post(`/admin/pages/${id}/publish`);
      toast.success("Page published.");
      load();
    } catch (e) {
      toast.error(e?.response?.data?.error || "Publish failed.");
    }
  }

  async function unpublish(id) {
    try {
      await api.post(`/admin/pages/${id}/unpublish`);
      toast.success("Page unpublished.");
      load();
    } catch (e) {
      toast.error(e?.response?.data?.error || "Unpublish failed.");
    }
  }

  // optional: confirm delete via modal-like confirm (still no window.confirm)
  const [confirmDelete, setConfirmDelete] = useState({
    open: false,
    id: null,
    title: "",
  });

  function askDelete(p) {
    setConfirmDelete({ open: true, id: p.id, title: p.title });
  }

  async function doDelete() {
    const id = confirmDelete.id;
    if (!id) return;

    try {
      await api.delete(`/admin/pages/${id}`);
      toast.success("Page deleted.");
      setConfirmDelete({ open: false, id: null, title: "" });
      load();
    } catch (e) {
      toast.error(e?.response?.data?.error || "Delete failed.");
    }
  }

  return (
    <div className="ap-root">
      <ToastHost items={toast.toasts} />

      {/* New Page Modal */}
      <Modal open={openNew} title="Create new page" onClose={closeCreate}>
        <div style={{ display: "grid", gap: 12 }}>
          <div style={{ color: "rgba(255,255,255,0.72)", fontSize: 13 }}>
            Create a new static page (e.g., Home, About, Privacy, Terms). You
            can edit the content after creating it.
          </div>

          <div style={{ display: "grid", gap: 6 }}>
            <label style={{ fontSize: 13, color: "rgba(255,255,255,0.78)" }}>
              Page title
            </label>
            <input
              ref={titleRef}
              value={newTitle}
              onChange={(e) => setNewTitle(e.target.value)}
              placeholder="e.g., Home"
              className="ap-input"
              style={{
                width: "100%",
                padding: "10px 12px",
                borderRadius: 12,
                border: "1px solid rgba(255,255,255,0.10)",
                background: "rgba(0,0,0,0.35)",
                color: "rgba(255,255,255,0.92)",
                outline: "none",
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter") confirmCreate();
              }}
            />
          </div>

          <div style={{ display: "grid", gap: 6 }}>
            <label style={{ fontSize: 13, color: "rgba(255,255,255,0.78)" }}>
              Slug
            </label>
            <input
              value={newSlug}
              onChange={(e) => setNewSlug(e.target.value)}
              placeholder="e.g., home"
              className="ap-input"
              style={{
                width: "100%",
                padding: "10px 12px",
                borderRadius: 12,
                border: "1px solid rgba(255,255,255,0.10)",
                background: "rgba(0,0,0,0.35)",
                color: "rgba(255,255,255,0.92)",
                outline: "none",
                fontFamily:
                  "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace",
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter") confirmCreate();
              }}
            />
            <div style={{ fontSize: 12, color: "rgba(255,255,255,0.55)" }}>
              Preview URL:{" "}
              <span style={{ color: "rgba(255,255,255,0.75)" }}>
                /p/{slugify(newSlug || autoSlug)}
              </span>
            </div>
          </div>

          <div
            style={{
              display: "flex",
              justifyContent: "flex-end",
              gap: 10,
              marginTop: 6,
            }}
          >
            <button
              className="ap-btn"
              onClick={closeCreate}
              disabled={creating}
            >
              Cancel
            </button>
            <button
              className="ap-btn ap-btnPrimary"
              onClick={confirmCreate}
              disabled={creating}
            >
              {creating ? "Creating…" : "Create"}
            </button>
          </div>
        </div>
      </Modal>

      {/* Delete Confirm Modal */}
      <Modal
        open={confirmDelete.open}
        title="Delete page?"
        onClose={() => setConfirmDelete({ open: false, id: null, title: "" })}
      >
        <div style={{ display: "grid", gap: 12 }}>
          <div style={{ color: "rgba(255,255,255,0.78)" }}>
            This will permanently delete <b>{confirmDelete.title}</b>. This
            cannot be undone.
          </div>
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 10 }}>
            <button
              className="ap-btn"
              onClick={() =>
                setConfirmDelete({ open: false, id: null, title: "" })
              }
            >
              Cancel
            </button>
            <button className="ap-btn ap-btnDanger" onClick={doDelete}>
              Delete
            </button>
          </div>
        </div>
      </Modal>

      <div className="ap-head">
        <div>
          <div className="ap-title">Pages</div>
          <div className="ap-sub">
            Edit static pages like About, Privacy, Terms, Contact.
          </div>
        </div>

        <button className="ap-btn ap-btnPrimary" onClick={openCreate}>
          + New Page
        </button>
      </div>

      <div className="ap-card">
        {loading ? (
          <div className="ap-loading">Loading…</div>
        ) : pages.length === 0 ? (
          <div className="ap-empty">No pages yet.</div>
        ) : (
          <table className="ap-table">
            <thead>
              <tr>
                <th>Title</th>
                <th>Slug</th>
                <th>Status</th>
                <th>Updated</th>
                <th style={{ textAlign: "right" }}>Actions</th>
              </tr>
            </thead>

            <tbody>
              {pages.map((p) => (
                <tr key={p.id}>
                  <td className="ap-strong">{p.title}</td>
                  <td className="ap-mono">{p.slug}</td>
                  <td>
                    <span
                      className={`ap-badge ${p.status === "published" ? "ok" : ""}`}
                    >
                      {p.status}
                    </span>
                  </td>
                  <td>
                    {p.updated_at
                      ? new Date(p.updated_at).toLocaleString()
                      : ""}
                  </td>
                  <td style={{ textAlign: "right" }}>
                    <button
                      className="ap-btn"
                      onClick={() => nav(`/admin/pages/${p.id}`)}
                    >
                      Edit
                    </button>

                    <button
                      className="ap-btn"
                      onClick={() => nav(`/p/${p.slug}`)}
                    >
                      Preview
                    </button>

                    {p.status === "published" ? (
                      <button
                        className="ap-btn"
                        onClick={() => unpublish(p.id)}
                      >
                        Unpublish
                      </button>
                    ) : (
                      <button
                        className="ap-btn ap-btnPrimary"
                        onClick={() => publish(p.id)}
                      >
                        Publish
                      </button>
                    )}

                    <button
                      className="ap-btn ap-btnDanger"
                      onClick={() => askDelete(p)}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
